BEGIN;

ON CONFLICT(id) DO NOTHING;

ON CONFLICT(id) DO NOTHING;

ON CONFLICT(id) DO NOTHING;

WITH preview_parties(id,tenant_id,project_id,contract_id,party_id,participant_role,signing_required,signature_status,signed_at,signed_version_id) AS (VALUES
 ('bd400000-0000-4000-8000-000000000001','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000001','bd200000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001','buyer',true,'signed','2026-07-04','bd300000-0000-4000-8000-000000000004'),
 ('bd400000-0000-4000-8000-000000000002','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000001','bd200000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000002','co_buyer',true,'signed','2026-07-04','bd300000-0000-4000-8000-000000000004'),
 ('bd400000-0000-4000-8000-000000000003','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000001','bd200000-0000-4000-8000-000000000002','c0000000-0000-4000-8000-000000000007','buyer',true,'pending',NULL,NULL),
 ('bd400000-0000-4000-8000-000000000004','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000001','bd200000-0000-4000-8000-000000000003','c0000000-0000-4000-8000-000000000003','buyer',true,'signed','2026-06-02','bd300000-0000-4000-8000-000000000007'),
 ('bd400000-0000-4000-8000-000000000005','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002','bd200000-0000-4000-8000-000000000004','c0000000-0000-4000-8000-000000000005','buyer',true,'signed','2026-04-01','bd300000-0000-4000-8000-000000000008'),
 ('bd400000-0000-4000-8000-000000000006','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002','bd200000-0000-4000-8000-000000000005','c0000000-0000-4000-8000-000000000008','buyer',true,'signed','2026-02-01','bd300000-0000-4000-8000-000000000009'),
 ('bd400000-0000-4000-8000-000000000007','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002','bd200000-0000-4000-8000-000000000006','c0000000-0000-4000-8000-000000000004','buyer',true,'signed','2026-06-01','bd300000-0000-4000-8000-000000000010'),
 ('bd400000-0000-4000-8000-000000000008','d0000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000002','bd200000-0000-4000-8000-000000000007','c0000000-0000-4000-8000-000000000004','buyer',true,'pending',NULL,NULL)
)
SELECT preview.id::uuid,preview.tenant_id::uuid,preview.project_id::uuid,preview.contract_id::uuid,preview.party_id::uuid,
  preview.participant_role,preview.signing_required,preview.signature_status,preview.signed_at::timestamptz,preview.signed_version_id::uuid
FROM preview_parties preview
WHERE NOT EXISTS (SELECT 1 FROM contract_parties existing WHERE existing.id=preview.id::uuid);

SELECT set_config('app.contract_status_command','on',true);
UPDATE contracts SET current_status='signed',signed_at=CASE id
  WHEN 'bd200000-0000-4000-8000-000000000001' THEN '2026-07-04'::timestamptz
  WHEN 'bd200000-0000-4000-8000-000000000003' THEN '2026-06-02'::timestamptz
  WHEN 'bd200000-0000-4000-8000-000000000004' THEN '2026-04-01'::timestamptz
  WHEN 'bd200000-0000-4000-8000-000000000005' THEN '2026-02-01'::timestamptz
  WHEN 'bd200000-0000-4000-8000-000000000006' THEN '2026-06-01'::timestamptz END
WHERE id IN ('bd200000-0000-4000-8000-000000000001','bd200000-0000-4000-8000-000000000003','bd200000-0000-4000-8000-000000000004','bd200000-0000-4000-8000-000000000005','bd200000-0000-4000-8000-000000000006')
  AND current_status='signing';

SELECT ('bd500000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY id)::text,12,'0'))::uuid,tenant_id,project_id,id,NULL,current_status,'seed','Výchozí smluvní workflow preview',created_at,created_by_membership_id
FROM contracts WHERE tenant_id='d0000000-0000-4000-8000-000000000001'
ON CONFLICT(id) DO NOTHING;

COMMIT;
